// ===== Model =====
public class Product
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public decimal Price { get; set; }
}

public interface IProductRepository
{
    Task<IEnumerable<Product>> GetAllAsync();
    Task SaveAsync(Product product);
    Task DeleteAsync(int id);
}

// ===== ViewModel (MVVM Toolkit) =====
using CommunityToolkit.Mvvm.ComponentModel;
using CommunityToolkit.Mvvm.Input;
using CommunityToolkit.Mvvm.Messaging;

public record ProductChangedMessage(int ProductId);

public partial class ProductListViewModel : ObservableObject, IRecipient<ProductChangedMessage>
{
    private readonly IProductRepository _repository;
    private readonly IDialogService _dialog;

    public ProductListViewModel(IProductRepository repository, IDialogService dialog)
    {
        _repository = repository;
        _dialog = dialog;
        WeakReferenceMessenger.Default.Register(this);
    }

    [ObservableProperty]
    private ObservableCollection<Product> _products = new();

    [ObservableProperty]
    private Product? _selectedProduct;

    [ObservableProperty]
    private bool _isBusy;

    // CanExecute 自动随 SelectedProduct 变化更新按钮可用状态
    [RelayCommand(CanExecute = nameof(HasSelection))]
    private async Task DeleteAsync()
    {
        if (SelectedProduct is null) return;
        bool confirmed = await _dialog.ShowConfirmationAsync("确认", "删除该产品？");
        if (!confirmed) return;

        IsBusy = true;
        try
        {
            await _repository.DeleteAsync(SelectedProduct.Id);
            Products.Remove(SelectedProduct);
            WeakReferenceMessenger.Default.Send(new ProductChangedMessage(SelectedProduct.Id));
        }
        finally { IsBusy = false; }
    }

    private bool HasSelection() => SelectedProduct is not null;

    partial void OnSelectedProductChanged(Product? value) => DeleteCommand.NotifyCanExecuteChanged();

    [RelayCommand]
    private async Task LoadAsync()
    {
        IsBusy = true;
        try
        {
            var items = await _repository.GetAllAsync();
            Products = new ObservableCollection<Product>(items);
        }
        finally { IsBusy = false; }
    }

    // 收到其他页面的修改消息后刷新
    public void Receive(ProductChangedMessage message) => LoadCommand.Execute(null);
}

// ===== ViewModel (ReactiveUI: 搜索防抖示例) =====
using ReactiveUI;
using System.Reactive;
using System.Reactive.Linq;

public class SearchViewModel : ReactiveObject
{
    private string _searchText = string.Empty;
    public string SearchText
    {
        get => _searchText;
        set => this.RaiseAndSetIfChanged(ref _searchText, value);
    }

    private ObservableAsPropertyHelper<List<string>> _results;
    public List<string> Results => _results.Value;

    public ReactiveCommand<string, List<string>> SearchCommand { get; }

    public SearchViewModel(IProductRepository repository)
    {
        // 输入防抖 300ms → 执行搜索，结果自动绑定到 Results
        var canSearch = this.WhenAnyValue(x => x.SearchText)
            .Select(s => !string.IsNullOrWhiteSpace(s));

        SearchCommand = ReactiveCommand.CreateFromTask(
            async (string query) =>
            {
                var products = await repository.GetAllAsync();
                return products.Where(p => p.Name.Contains(query)).Select(p => p.Name).ToList();
            },
            canSearch);

        // Throttle 防抖：用户停止输入 300ms 后才触发搜索
        this.WhenAnyValue(x => x.SearchText)
            .Throttle(TimeSpan.FromMilliseconds(300), RxApp.MainThreadScheduler)
            .Where(s => !string.IsNullOrWhiteSpace(s))
            .InvokeCommand(SearchCommand);

        // 搜索结果自动映射到 Results 属性
        SearchCommand.ToProperty(this, x => x.Results, out _results);
    }
}

// ===== DI 注册 =====
public static class ServiceCollectionExtensions
{
    public static IServiceCollection AddAppServices(this IServiceCollection services)
    {
        services.AddSingleton<IProductRepository, ProductRepository>();
        services.AddSingleton<IDialogService, DialogService>();
        services.AddTransient<ProductListViewModel>();
        services.AddTransient<SearchViewModel>();
        return services;
    }
}

// ===== 单元测试 =====
using Moq;

[TestClass]
public class ProductListViewModelTests
{
    [TestMethod]
    public async Task Delete_SelectedProduct_RemovesFromList()
    {
        // Arrange
        var repo = new Mock<IProductRepository>();
        var dialog = new Mock<IDialogService>();
        dialog.Setup(d => d.ShowConfirmationAsync(It.IsAny<string>(), It.IsAny<string>()))
              .ReturnsAsync(true);

        var vm = new ProductListViewModel(repo.Object, dialog.Object);
        var product = new Product { Id = 1, Name = "Test" };
        vm.Products = new ObservableCollection<Product> { product };
        vm.SelectedProduct = product;

        // Act
        await vm.DeleteCommand.ExecuteAsync(null);

        // Assert
        Assert.AreEqual(0, vm.Products.Count);
        repo.Verify(r => r.DeleteAsync(1), Times.Once);
    }
}

